const fs=require('fs'),path=require('path'),vm=require('vm'),assert=require('assert/strict');
const root=path.join(__dirname,process.argv.includes('--tree')?'skill-tree-20261006':process.argv.includes('--scale')?'creature-scale-20261006':process.argv.includes('--soul')?'adventure-soul-20261006':'combat-boss-director-20261006'),file=fs.readFileSync(path.join(root,'boss-director.js'),'utf8'),api=require(path.join(root,'boss-director.js')),html=fs.readFileSync(path.join(root,'index.html'),'utf8');
for(const m of html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g))new vm.Script(m[1]);
const results=[];const check=(label,fn)=>{fn();results.push(label)};
check('32 encounter profiles',()=>assert.equal(Object.keys(api.profiles).length,32));
const u=(kind,o={})=>({kind,alive:true,hp:100,mhp:100,...o});
check('no universal half-HP trigger',()=>assert.ok(Object.values(api.profiles).every(p=>p.triggers.every(t=>t.hp!==.5))));
check('solo bosses never auto-summon',()=>{for(const k of ['goat','ignis','hanzo','odin','beast_bash','beast_kusa','beast_urid','beast_ushu'])assert.equal(api.get(k).waves?.length||0,0)});
check('turn gate ignores low HP',()=>{assert.equal(api.ready(u('grom',{hp:1,bossTurns:2})),false);assert.equal(api.ready(u('grom',{bossTurns:3})),true)});
check('65% and 35% gates are different',()=>{assert.equal(api.ready(u('selena',{hp:64})),true);assert.equal(api.ready(u('ignis',{hp:50})),false);assert.equal(api.ready(u('ignis',{hp:34})),true)});
check('effective hit gate, not health',()=>{assert.equal(api.ready(u('beast_mmah',{hp:1,bossHits:3})),false);assert.equal(api.ready(u('beast_mmah',{bossHits:4})),true)});
check('two final phases',()=>{assert.equal(api.ready(u('babel_beast',{hp:74})),true);assert.equal(api.ready(u('babel_beast',{hp:50,bossStage:1})),false);assert.equal(api.ready(u('babel_beast',{hp:34,bossStage:1})),true);assert.equal(api.ready(u('babel_beast',{hp:1,bossStage:2})),false)});
check('dead/applying/completed guards',()=>{assert.equal(api.ready(u('grom',{bossTurns:3,alive:false})),false);assert.equal(api.ready(u('grom',{bossTurns:3,_bdApplying:true})),false);assert.equal(api.ready(u('grom',{bossTurns:3,bossStage:1})),false)});
const tile=(x,z)=>x>=0&&x<12&&z>=0&&z<12?{x,z,h:0,type:'g'}:null;
const context={console,Math,Set,document:{documentElement:{dataset:{}},createElement:()=>({setAttribute(){}}),querySelector:()=>({appendChild(){}})},units:[],MONS:{},REACT:{},STAR_DEF:[],SK:{},mode:'battle',ELC:{水:'#88aaff',地:'#bba077',火:'#ff9955',風:'#99ddbb',光:'#ffeeaa',闇:'#9988bb'},T:tile,walkable:t=>!!t,unitAt(x,z){return context.units.find(u=>u.alive&&u.x===x&&u.z===z)},scene:{add(m){m.parent=this},remove(m){m.parent=null}},THREE:{PlaneGeometry:class{dispose(){}},MeshBasicMaterial:class{dispose(){}},Mesh:class{constructor(g,m){this.geometry=g;this.material=m;this.rotation={};this.position={set(){}}}}},TEX:{circle:{}},topY:()=>0,loadStageTiles(){},bossKit:()=>({acts:['strike'],charge:'strike'}),bossEnrage:async()=>{},calc:()=>({v:100,mods:[]}),dealDamage:async(a,d)=>{d.hp-=10;return 10},persuadeChance:()=>80,bossTargets:()=>null,validTargets:()=>[],areaTiles:()=>[],affected:()=>[],SIDE:x=>x.team==='enemy'?'E':'P',aiTurn:async()=>{},ko:async d=>{d.alive=false},floatText(){},impact(){},tileCenter:(x,z)=>({x,z}),toast(){},focusOn(){},bigText(){},sfx(){},chargeFx:async()=>{},holyLight:async()=>{},wait:async()=>{},bgm(){},say:async()=>{},drawBar(){},renderOrder(){},openOvl(){},closeOvl(){}};
for(const k of ['golem','slime','refr','crab','salam','dryad','ash','hawk','tengu','centip','kensei','imp'])context.MONS[k]={basic:'strike',st:{},nm:k};for(const k of Object.keys(api.profiles))context.MONS[k]={boss:1,tip:'　【狂暴】半血以後更強，還會叫手下。'};
context.makeUnit=o=>{const d={id:context.units.length+1,alive:true,...o,hp:o.st.hp,mhp:o.st.hp};context.units.push(d);return d};context.envDamage=async(d,n)=>{d.hp=Math.max(0,d.hp-n)};
context.bossTurn=async(b,foes)=>{if(context.BossDirector.ready(b))await context.bossEnrage(b);b.actions=(b.actions||0)+1};
context.window=context;vm.createContext(context);vm.runInContext(file,context);const rt=context.BossDirector.runtime;
async function runtimeTests(){
 const b=u('grom',{id:10,team:'enemy',lv:8,x:5,z:5,face:[0,1],boss:true,bossTurns:3});context.units.push(b);await context.bossEnrage(b);assert.equal(context.units.filter(a=>a.bdOwner===10).length,2);assert.equal(b.bossStage,1);await context.bossEnrage(b);assert.equal(context.units.filter(a=>a.bdOwner===10).length,2);assert.equal(await rt.summon(b,context.BossDirector.get(b),0),0);results.push('one typed wave, no repeat or duplicate');
 assert.equal(context.calc({},b,{kind:'phys'}).v,65);for(const a of context.units.filter(a=>a.bdOwner===10))a.alive=false;assert.equal(context.calc({},b,{kind:'phys'}).v,100);results.push('bodyguards break when killed');
 b.bossGuard=1;assert.equal(context.calc({},b,{kind:'phys'}).v,55);assert.equal(context.calc({},b,{kind:'mag'}).v,100);await context.dealDamage({},b,{kind:'phys'});assert.equal(b.bossGuard,0);results.push('physical guard consumed by actual damage; magic bypass');
 const h={id:100,alive:true,hp:100,mhp:100,team:'hero',x:4,z:4,cls:'support'},f=u('ignis',{id:99,boss:true,team:'enemy',lv:10,x:5,z:5,face:[0,1],hp:100,bossTurns:1});context.units.push(f,h);await context.bossTurn(f,[h]);assert.equal(f._bdHazards.length,1);assert.equal(h.hp,100);h.x=3;await context.bossTurn(f,[h]);assert.equal(h.hp,100);results.push('hazards telegraph one boss turn and can be escaped');
 await context.bossTurn(f,[h]);await context.bossTurn(f,[h]);assert.equal(h.hp,88);results.push('standing in a telegraph resolves bounded 12% damage');
 const owner=u('selena',{id:200,boss:true,team:'enemy',lv:9,x:6,z:6,face:[0,1],hp:40});context.units.push(owner);const healer={id:201,alive:true,bdOwner:200,bdRole:'healer',team:'enemy'};context.units.push(healer);await context.aiTurn(healer);assert.equal(owner.hp,46);await context.aiTurn(healer);assert.equal(owner.hp,46);results.push('healer restores 6% once per two turns');
 assert.equal(context.persuadeChance({},healer),0);results.push('summon bindings cannot be recruited');
 const final=u('babel_beast',{id:300,boss:true,team:'enemy',lv:19,x:5,z:7,face:[0,1],hp:30});context.units.push(final);await context.bossEnrage(final);await context.bossEnrage(final);assert.equal(final.bdSummoned,3);await context.bossEnrage(final);assert.equal(final.bdSummoned,3);results.push('final boss phases stop at two and three total reinforcements');
 context.loadStageTiles();assert.equal(f._bdHazards.length,0);results.push('hazards cleaned on stage change');
 console.log(JSON.stringify({passed:results.length,results},null,2));
}
runtimeTests().catch(e=>{console.error(e);process.exitCode=1});
